function parseExchangeAllowlist(rawList) {
  if (!rawList) return [];
  return String(rawList).split(",").map((v) => String(v || "").trim().toLowerCase()).filter(Boolean);
}
function getEnabledExecutionExchanges(env2) {
  const allowlistRaw = resolveEnvKey(env2, "EXECUTION_EXCHANGES_ALLOWLIST") || resolveEnvKey(env2, "ACTIVE_EXECUTION_EXCHANGES");
  const allowlist = parseExchangeAllowlist(allowlistRaw);
  if (allowlist.length === 0) {
    return [...ACTIVE_EXECUTION_EXCHANGES];
  }
  const allowedSet = new Set(allowlist);
  return ACTIVE_EXECUTION_EXCHANGES.filter((ex) => allowedSet.has(ex));
}
function isExecutionExchangeEnabled(env2, exchange) {
  const normalized = String(exchange || "").toLowerCase();
  if (!normalized) return false;
  return getEnabledExecutionExchanges(env2).includes(normalized);
}
function hasExchangeCredentials(env2, exchange) {
  const normalized = String(exchange || "").toLowerCase();
  if (!isExecutionExchangeEnabled(env2, normalized)) return false;
  const keys = EXCHANGE_CRED_KEYS[normalized];
  if (!keys) return false;
  return keys.every((k) => !!resolveEnvKey(env2, k));
}
function getRequiredCredentialKeys(exchange) {
  return EXCHANGE_CRED_KEYS[exchange?.toLowerCase()] || [];
}
function getMissingCredentialKeys(env2, exchange) {
  const keys = EXCHANGE_CRED_KEYS[exchange?.toLowerCase()] || [];
  return keys.filter((k) => !resolveEnvKey(env2, k)).map((k) => {
    const aliases = CRED_ALIASES[k];
    return aliases?.length ? `${k} (or ${aliases.join(" or ")})` : k;
  });
}
function getConfiguredExchanges(env2) {
  return getEnabledExecutionExchanges(env2).filter((ex) => hasExchangeCredentials(env2, ex));
}
async function selectBestExchange(env2, requiredUsd) {
  const PRIORITY = ["mexc", "bitget"];
  const configured = getConfiguredExchanges(env2);
  if (configured.length === 0) return null;
  const sorted = [...configured].sort((a, b) => {
    const pa = PRIORITY.indexOf(a);
    const pb = PRIORITY.indexOf(b);
    if (pa !== -1 && pb !== -1) return pa - pb;
    if (pa !== -1) return -1;
    if (pb !== -1) return 1;
    return a.localeCompare(b);
  });
  const balances = await Promise.allSettled(
    sorted.map(async (ex) => ({ ex, bal: await getExchangeBalance(env2, ex, "USDT") }))
  );
  let bestEx = null;
  let bestBal = 0;
  for (const result of balances) {
    if (result.status !== "fulfilled") continue;
    const { ex, bal } = result.value;
    if (bal < requiredUsd) continue;
    const currentPriority = bestEx ? PRIORITY.indexOf(bestEx) : -2;
    const candidatePriority = PRIORITY.indexOf(ex);
    const higherBalance = bal > bestBal;
    const samePriorityOrBetter = bestEx === null || candidatePriority !== -1 && (currentPriority === -1 || candidatePriority < currentPriority) || candidatePriority === currentPriority && higherBalance;
    if (higherBalance || samePriorityOrBetter) {
      bestEx = ex;
      bestBal = bal;
    }
  }
  return bestEx;
}
async function getExchangeBalance(env2, exchange, asset = "USDT") {
  switch (exchange?.toLowerCase()) {
    case "mexc":
      return (await getMEXCBalance(env2, asset)).free;
    case "binance":
      return (await getBinanceBalance(env2, asset)).free;
    case "kucoin":
      return (await getKuCoinBalance(env2, asset)).free;
    case "bitget":
      return (await getBitgetBalance(env2, asset)).free;
    case "bitmart":
      return (await getBitmartBalance(env2, asset)).free;
    case "htx":
      return (await getHTXBalance(env2, asset.toLowerCase())).free;
    // bybit/gateio: data-only, no live execution
    default:
      return 0;
  }
}
