  function parseLocalizedNumber(rawValue, fallback = NaN){
    if (rawValue == null) return fallback;
    const normalized = String(rawValue)
      .trim()
      .replace(/[\u0660-\u0669]/g, (d) => String(d.charCodeAt(0) - 1632))
      .replace(/[\u06F0-\u06F9]/g, (d) => String(d.charCodeAt(0) - 1776))
      .replace(/\u060C/g, ',')
      .replace(/[ \\t\\n\\r\\f\\v]+/g, '')
      .replace(',', '.');
    const n = Number(normalized);
    return Number.isFinite(n) ? n : fallback;
  }

  function readNumericInput(id, fallback = NaN){
    const el = document.getElementById(id);
    return parseLocalizedNumber(el?.value, fallback);
  }

  async function saveConfig(){
    const body={
      max_daily_loss_usd:         readNumericInput('maxDailyLoss'),
      daily_limit_usd:            readNumericInput('dailyLimitUsd'),
      max_per_trade_loss_pct:     readNumericInput('maxPerTrade'),
      min_seconds_between_trades: readNumericInput('minSeconds'),
      initial_capital:            readNumericInput('initialCapital'),
      position_size_usd:          readNumericInput('positionSizeUsd', 5),
      multi_strategy_live:        !!document.getElementById('multiStrategyLive')?.checked,
      max_live_trades_per_scan:   Math.floor(readNumericInput('maxLiveTradesPerScan', 3)),
      scan_symbol_mode:           document.getElementById('scanSymbolMode')?.value || 'cex_union',
      max_dynamic_symbols:        Math.floor(readNumericInput('maxDynamicSymbols', 500)),
      max_metamask_symbols:       Math.floor(readNumericInput('maxMetaMaskSymbols', 10000)),
      scan_quote_assets:          String(document.getElementById('scanQuoteAssets')?.value || '').split(',').map(v=>v.trim()).filter(Boolean),
      use_dynamic_symbols:        !!document.getElementById('useDynamicSymbols')?.checked,
      strategy_flags: {
        cex:         !!document.getElementById('flag_cex')?.checked,
        dex:         !!document.getElementById('flag_dex')?.checked,
        perps:       !!document.getElementById('flag_perps')?.checked,
        funding:     !!document.getElementById('flag_funding')?.checked,
        triangular:  !!document.getElementById('flag_triangular')?.checked,
        statistical: !!document.getElementById('flag_statistical')?.checked,
        scalp_forward: !!document.getElementById('flag_scalp_forward')?.checked,
        scalp_reverse: !!document.getElementById('flag_scalp_reverse')?.checked,
        scalp_parallel: !!document.getElementById('flag_scalp_parallel')?.checked,
      }
    };
    if (!body.strategy_flags.perps) {
      body.strategy_flags.funding = false;
    }
    if (spotOnlyLockEnabled) {
      body.strategy_flags.perps = false;
      body.strategy_flags.funding = false;
      body.spot_only_lock = true;
    }
    const numericKeys=['max_daily_loss_usd','daily_limit_usd','max_per_trade_loss_pct','min_seconds_between_trades','initial_capital','max_live_trades_per_scan','position_size_usd','max_dynamic_symbols','max_metamask_symbols'];
    for(const k of numericKeys){
      const v=Number(body[k]);
      if(!Number.isFinite(v)||v<=0){ alert('\u274C \u0642\u064A\u0645\u0629 \u063A\u064A\u0631 \u0635\u062D\u064A\u062D\u0629: '+k); return; }
    }
    // Enforce position size safety bounds in the UI
    if (body.position_size_usd < 1 || body.position_size_usd > 500) {
      alert('\u274C \u062D\u062C\u0645 \u0627\u0644\u0645\u0631\u0643\u0632 \u064A\u062C\u0628 \u0623\u0646 \u064A\u0643\u0648\u0646 \u0628\u064A\u0646 1 \u0648 500 USDT'); return;
    }
    setButtonsBusy(true);
    try{
      await callAdminApi('/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
      alert('\u2705 \u062A\u0645 \u062D\u0641\u0638 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A'); location.reload();
    }catch(e){ alert('\u274C '+e.message); }
    finally{ setButtonsBusy(false); }
  }

  function setPerpsUiEnabled(enabled){
    const show = enabled !== false;
    ['strategy-card-perps','summary-card-perps','panel-perps-status','panel-perps-wallet'].forEach((id)=>{
      const el = document.getElementById(id);
      if (el) el.style.display = show ? '' : 'none';
    });
    const perps = document.getElementById('flag_perps');
    if (perps) {
      perps.disabled = spotOnlyLockEnabled;
      if (spotOnlyLockEnabled) perps.checked = false;
    }
    const funding = document.getElementById('flag_funding');
    if (funding) {
      funding.disabled = !show || spotOnlyLockEnabled;
      if (!show || spotOnlyLockEnabled) funding.checked = false;
    }
  }

  const perpsToggle = document.getElementById('flag_perps');
  if (perpsToggle) {
    perpsToggle.addEventListener('change', () => {
      setPerpsUiEnabled(!!perpsToggle.checked);
    });
  }

