    const recs  = document.getElementById('botMemoryRecommendations');
    panel.style.display = 'block';
    stats.innerHTML = '<span style="color:#888">\u23F3 \u062C\u0627\u0631\u064D \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u0630\u0627\u0643\u0631\u0629...</span>';
